  if(path === '/category-art.png'){response.writeHead(200,{...baseHeaders,'Content-Type':'image/png','Cache-Control':'public,max-age=86400'});response.end(Uint8Array.from(atob(categoryArt),c=>c.charCodeAt(0)));return;}

